// A function intended only for integers
bool isLucky(int number);

// Delete overloads to prevent unwanted implicit conversions
bool isLucky(char) = delete;
bool isLucky(bool) = delete;
bool isLucky(double) = delete; // Also catches floats due to promotion

void test() {
    isLucky(13);      // OK: calls the int version
    // isLucky('a');  // Compile Error: calls deleted char overload
    // isLucky(true); // Compile Error: calls deleted bool overload
    // isLucky(3.5);  // Compile Error: calls deleted double overload
    // isLucky(3.5f); // Compile Error: float promotes to double,
                      // calls deleted double overload
}
